import os, glob, numpy as np, pandas as pd
import matplotlib.pyplot as plt
%matplotlib inline

MAD_MAX, EDGE_TRIM_CM, POLARITY_SIGN, SMOOTH_CM, MIN_ZONE_CM2 = 12.0, 5.0, -1, 7, 12
PCA_DIR = "OSU_uchannel_magnetometer_NRM_data/ucheck_spike_removed/dir/pca_corrected"

# core geometry (foam) -> viable (non-foam) position ranges per group
groups = {"Group 1":["TAM 1","TAM 2","TAM 3B"],"Group 2":["TAM 3A","TAM 4","TAM 5E","TAM 5D","TAM 5C"],
 "Group 3":["TAM 5B","TAM 5A","TAM 6","TAM 7"],"Group 4":["SC 1C","SC 1B","SC 1A","SC 2","SC 3C"],
 "Group 5":["SC 3B","SC 3A","SC 4D","SC 4C","SC 4B","SC 4A"],"Group 6":["SC 5","SC 6","SC 7C","SC 7B","SC 7A"],
 "Group 7":["SC 8"]}
geom={}
for c,l,a,b in zip(["SC 1C","SC 1B","SC 1A","SC 2","SC 3C","SC 3B","SC 3A","SC 4D","SC 4C","SC 4B","SC 4A","SC 5","SC 6","SC 7C","SC 7B","SC 7A","SC 8"],
    [18.5,13,8,50,34,27.5,20,24,16,26.5,22.5,23,50,14,13.5,13,50],[1,2.5,4,7.5,1.2,1.5,3.6,4.5,.25,1.5,.5,2.5,3,2,1,1.5,15],[1,5,4,15.5,3.5,3,2.5,7,.5,2,.25,3.5,2,1.5,1.5,2,8]):
    geom[c]=dict(length=l,above=a,below=b)
for c,l,a,b in zip(["TAM 1","TAM 2","TAM 3B","TAM 3A","TAM 4","TAM 5E","TAM 5D","TAM 5C","TAM 5B","TAM 5A","TAM 6","TAM 7"],
    [75,50.5,13.6,36,74,12,11,10,8.5,7.8,50,49],[9,12.3,4.5,0,10,2.5,3,1.5,2.5,2,2.1,1],[9.2,7.5,0,0,7,2.1,2,1.5,2.3,1.5,2.5,.5]):
    geom[c]=dict(length=l,above=a,below=b)
viable={}
for g,cs in groups.items():
    x,r=0.0,[]
    for c in cs:
        gg=geom[c]; vs,ve=x+gg["above"],x+gg["length"]-gg["below"]
        if vs<ve: r.append([vs,ve])
        x+=gg["length"]
    viable[g]=r
GROUP_NAME={"TAM_1_2_3B":"Group 1","TAM_3A_4_5E_5D_5C":"Group 2","TAM_5B_5A_6_7":"Group 3",
 "SC_1C_1B_1A_2_3C":"Group 4","SC_3B_3A_4D_4C_4B_4A":"Group 5","SC_5_6_7C_7B_7A":"Group 6","SC_8":"Group 7"}
SITE_GROUPS={"TAM":["TAM_1_2_3B","TAM_3A_4_5E_5D_5C","TAM_5B_5A_6_7"],
 "SC":["SC_1C_1B_1A_2_3C","SC_3B_3A_4D_4C_4B_4A","SC_5_6_7C_7B_7A","SC_8"]}

def _load(path):
    rows=[r.rstrip("\n").split("\t") for r in open(path,errors="replace")]; h=rows[0]
    def ci(*n):
        for x in n:
            if x in h: return h.index(x)
    pi,di,ii,mi=ci("Position(cm)","position"),ci("Decl"),ci("Incl"),ci("MAD")
    out=[]
    for r in rows[1:]:
        try: out.append((float(r[pi]),float(r[di]),float(r[ii]),float(r[mi])))
        except: pass
    return pd.DataFrame(out,columns=["pos","dec","inc","mad"])
def gkey(f): return os.path.basename(f).split(" - ")[1].split(" (")[0].split("_NRM")[0]

fits={}
for f in sorted(glob.glob(os.path.join(PCA_DIR,"PCA*"))):
    df=_load(f)
    if df.empty: continue
    lo,hi=df.pos.min()+EDGE_TRIM_CM,df.pos.max()-EDGE_TRIM_CM
    fits[gkey(f)]=df[(df.mad<MAD_MAX)&(df.pos>=lo)&(df.pos<=hi)].reset_index(drop=True)

def runmed(v,p,w):
    return np.array([np.median(v[(p>=p[i]-w/2)&(p<=p[i]+w/2)]) for i in range(len(v))])
is_normal=lambda inc:(POLARITY_SIGN*inc)>0
def foam(g,df):
    r=viable.get(GROUP_NAME.get(g))
    if not r: return df.reset_index(drop=True)
    return df[df.pos.apply(lambda p:any(a<=p<=b for a,b in r))].reset_index(drop=True)
fits2={}
for g,df in fits.items():
    d=foam(g,df).copy()
    if len(d)<3: continue
    d["inc_s"]=runmed(d.inc.values,d.pos.values,SMOOTH_CM)
    step=np.diff(d.pos.values,prepend=d.pos.values[0]); step[step>3]=1.0
    d["sed"]=np.cumsum(step); fits2[g]=d
def zones(df,col="cdepth"):
    s=np.array([1 if is_normal(v) else -1 for v in df.inc_s]); pos=df[col].values
    b=[0]+[k for k in range(1,len(s)) if s[k]!=s[k-1]]+[len(s)]
    return [(pos[b[j]],pos[b[j+1]-1],"N" if s[b[j]]>0 else "R") for j in range(len(b)-1) if pos[b[j+1]-1]-pos[b[j]]>=MIN_ZONE_CM2]
def comp(site):
    parts,off=[],0.0
    for g in SITE_GROUPS[site]:
        if g not in fits2: continue
        d=fits2[g].copy(); d["cdepth"]=(d.sed-d.sed.min())+off; parts.append(d); off+=(d.sed.max()-d.sed.min())+1
    return pd.concat(parts,ignore_index=True) if parts else pd.DataFrame()
C={s:comp(s) for s in SITE_GROUPS}
for s,df in C.items():
    if df.empty: continue
    z=zones(df); print(f"{s}: {''.join(t[2] for t in z)}  ({len(z)} zones, {df.cdepth.max():.0f} cm)")
    fig,(a1,a2)=plt.subplots(1,2,figsize=(5,7),gridspec_kw={"width_ratios":[5,1]})
    a1.plot(df.inc,df.cdepth,lw=.5,color="0.7"); a1.plot(df.inc_s,df.cdepth,lw=1.3,color="k")
    a1.axvline(0,color="r",ls="--",lw=.8); a1.set_xlim(-90,90); a1.invert_yaxis()
    a1.set_xlabel("Inclination (deg)"); a1.set_ylabel("composite sediment depth (cm)"); a1.set_title(f"Site {s} (normal = neg incl)")
    for a,b,p in z: a2.axhspan(a,b,color=("k" if p=="N" else "w"),ec="k")
    a2.set_xlim(0,1); a2.set_xticks([]); a2.set_ylim(a1.get_ylim()); a2.set_title("pol")
    plt.tight_layout(); plt.show()
